/**
 * Sustainability Atlas logo, inlined as a base64 PNG data URI.
 *
 * The backend cannot read `frontend/public/` at runtime — the API and frontend are built
 * into separate Docker images with no shared volume — so the asset that the UI serves as
 * a static file has to be embedded in backend source to reach the PDF renderer.
 *
 * Source: frontend/public/logo/SA-transparent.png (the same file
 * `frontend/components/layout/AppSidebar.vue` renders in the expanded sidebar).
 * 2676x714, 8-bit RGBA, non-interlaced — pdfkit rejects interlaced PNGs.
 *
 * Regenerate with:
 *   node -e "console.log('data:image/png;base64,'+require('fs').readFileSync('frontend/public/logo/SA-transparent.png').toString('base64'))"
 */

/** Native pixel dimensions, so callers can preserve the aspect ratio instead of stretching. */
export const SA_LOGO_WIDTH_PX = 2676;
export const SA_LOGO_HEIGHT_PX = 714;
export const SA_LOGO_ASPECT = SA_LOGO_WIDTH_PX / SA_LOGO_HEIGHT_PX;

/* eslint-disable max-len */
export const SA_LOGO_DATA_URI =
    'data:image/png;base64,';
/* eslint-enable max-len */
